import { useState, type ReactNode } from 'react';
import {
  Activity, Ambulance, ArrowDownRight, ArrowUpRight, Bell, CarFront,
  Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Clock3,
  Command, Download, FileClock, Filter, Gauge, HeartPulse, History as HistoryIcon,
  Hospital, LayoutDashboard, ListFilter, MapPin, Menu, MessageSquare,
  Phone, Play, Radio, RefreshCw, Search, Send,
  Settings, Shield, Siren, SlidersHorizontal, Sparkles, Square, Stethoscope,
  UserRound, Users, X, Zap, type LucideIcon,
} from 'lucide-react';
import { Link, Redirect, Route, Switch, useLocation } from 'wouter';
import {
  ambulances, drivers, history, hospitals, incidents, notifications, policeStations,
  responseTeams, vehicles, type Incident, type Severity,
} from './data/mock-data';

type Toast = { id: number; message: string; tone?: 'success' | 'warning' | 'info' };
type Icon = LucideIcon;

const pageMeta: Record<string, { title: string; description: string }> = {
  '/overview': { title: 'Operations overview', description: 'Live operating picture for the Bengaluru control center' },
  '/incidents': { title: 'Live incidents', description: 'Triage, dispatch and coordinate active responses' },
  '/vehicles': { title: 'Fleet readiness', description: 'Availability and deployment status across the response fleet' },
  '/drivers': { title: 'Driver roster', description: 'Shift coverage, assignments and contact availability' },
  '/emergency-services': { title: 'Emergency services', description: 'Hospitals, ambulances and police capacity in one view' },
  '/response-team': { title: 'Response teams', description: 'Coordinate specialist teams and readiness by zone' },
  '/history': { title: 'Incident history', description: 'Review completed events and operational outcomes' },
  '/analytics': { title: 'Operational analytics', description: 'Patterns and performance across the last 30 days' },
  '/demo': { title: 'Scenario simulator', description: 'Run a local response drill without contacting live services' },
  '/settings': { title: 'Control center settings', description: 'Configure display, alerts and operating preferences' },
};

const navGroups: { label: string; items: { href: string; label: string; icon: Icon }[] }[] = [
  { label: 'Command', items: [
    { href: '/overview', label: 'Overview', icon: LayoutDashboard },
    { href: '/incidents', label: 'Live incidents', icon: Siren },
  ] },
  { label: 'Resources', items: [
    { href: '/vehicles', label: 'Fleet readiness', icon: CarFront },
    { href: '/drivers', label: 'Driver roster', icon: UserRound },
    { href: '/emergency-services', label: 'Emergency services', icon: Hospital },
    { href: '/response-team', label: 'Response teams', icon: Users },
  ] },
  { label: 'Review', items: [
    { href: '/history', label: 'Incident history', icon: HistoryIcon },
    { href: '/analytics', label: 'Analytics', icon: Activity },
  ] },
  { label: 'Tools', items: [
    { href: '/demo', label: 'Scenario simulator', icon: Play },
    { href: '/settings', label: 'Settings', icon: Settings },
  ] },
];

function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(' ');
}

function StatusBadge({ label, tone = 'neutral' }: { label: string; tone?: string }) {
  const tones: Record<string, string> = {
    critical: 'bg-red-50 text-red-700 border-red-200',
    high: 'bg-orange-50 text-orange-700 border-orange-200',
    moderate: 'bg-amber-50 text-amber-700 border-amber-200',
    low: 'bg-sky-50 text-sky-700 border-sky-200',
    good: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    active: 'bg-red-50 text-red-700 border-red-200',
    dispatched: 'bg-cyan-50 text-cyan-700 border-cyan-200',
    monitoring: 'bg-amber-50 text-amber-700 border-amber-200',
    resolved: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    available: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    'on duty': 'bg-cyan-50 text-cyan-700 border-cyan-200',
    'on scene': 'bg-amber-50 text-amber-700 border-amber-200',
    'en route': 'bg-cyan-50 text-cyan-700 border-cyan-200',
    maintenance: 'bg-slate-100 text-slate-600 border-slate-200',
    busy: 'bg-orange-50 text-orange-700 border-orange-200',
    deployed: 'bg-cyan-50 text-cyan-700 border-cyan-200',
    'off duty': 'bg-slate-100 text-slate-600 border-slate-200',
    receiving: 'bg-amber-50 text-amber-700 border-amber-200',
    ready: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    transferred: 'bg-cyan-50 text-cyan-700 border-cyan-200',
  };
  const key = label.toLowerCase();
  return <span data-testid={`status-${key.replace(/\s/g, '-')}`} className={cn('inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.08em]', tones[key] || 'bg-slate-100 text-slate-600 border-slate-200')}><span className="h-1.5 w-1.5 rounded-full bg-current" />{label}</span>;
}

function MetricCard({ label, value, detail, icon: IconComponent, accent = 'teal', trend }: { label: string; value: string; detail: string; icon: Icon; accent?: string; trend?: 'up' | 'down' }) {
  const colors: Record<string, string> = { teal: 'bg-cyan-50 text-cyan-700', amber: 'bg-amber-50 text-amber-700', red: 'bg-red-50 text-red-700', blue: 'bg-blue-50 text-blue-700' };
  return <div data-testid={`metric-${label.toLowerCase().replace(/\s/g, '-')}`} className="rounded-xl border border-slate-200 bg-white p-4 shadow-[0_1px_2px_rgba(22,38,58,.03)]">
    <div className="flex items-start justify-between"><div className={cn('flex h-9 w-9 items-center justify-center rounded-lg', colors[accent])}><IconComponent size={17} /></div>{trend && <span className={cn('flex items-center gap-0.5 text-[11px] font-bold', trend === 'up' ? 'text-emerald-600' : 'text-orange-600')}>{trend === 'up' ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />} vs yesterday</span>}</div>
    <p className="mt-4 text-[11px] font-bold uppercase tracking-[.1em] text-slate-500">{label}</p>
    <p className="mt-1 font-mono text-2xl font-medium tracking-tight text-slate-800">{value}</p>
    <p className="mt-1 text-xs text-slate-500">{detail}</p>
  </div>;
}

function SectionHeading({ eyebrow, title, action, onAction }: { eyebrow?: string; title: string; action?: string; onAction?: () => void }) {
  return <div className="mb-4 flex items-end justify-between gap-3">
    <div><p className="font-mono text-[10px] uppercase tracking-[.14em] text-cyan-700">{eyebrow}</p><h2 className="mt-1 text-base font-extrabold tracking-tight text-slate-800">{title}</h2></div>
    {action && <button data-testid={`button-${action.toLowerCase().replace(/\s/g, '-')}`} onClick={onAction} className="inline-flex items-center gap-1 text-xs font-bold text-cyan-700 hover:text-cyan-900">{action}<ChevronRight size={14} /></button>}
  </div>;
}

function EmptyState({ title, detail, icon: IconComponent = ListFilter }: { title: string; detail: string; icon?: Icon }) {
  return <div data-testid="empty-state" className="flex min-h-48 flex-col items-center justify-center rounded-xl border border-dashed border-slate-300 bg-slate-50/60 p-8 text-center"><IconComponent size={26} className="text-slate-400" /><p className="mt-3 text-sm font-bold text-slate-700">{title}</p><p className="mt-1 max-w-xs text-xs leading-5 text-slate-500">{detail}</p></div>;
}

function AppShell({ children, toasts, pushToast }: { children: ReactNode; toasts: Toast[]; pushToast: (message: string, tone?: Toast['tone']) => void }) {
  const [location, setLocation] = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [locationOpen, setLocationOpen] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState('Bengaluru · Central');
  const [readNotifications, setReadNotifications] = useState<string[]>(notifications.filter((item) => !item.unread).map((item) => item.id));
  const meta = pageMeta[location] || pageMeta['/overview'];
  const unread = notifications.filter((item) => !readNotifications.includes(item.id)).length;

  const navigate = (href: string) => { setLocation(href); setMobileOpen(false); };
  const markAllRead = () => { setReadNotifications(notifications.map((item) => item.id)); pushToast('All notifications marked as read', 'success'); };
  return <div className="flex min-h-[100dvh] bg-[#f2f5f7] text-slate-800">
    {mobileOpen && <button aria-label="Close navigation" data-testid="button-close-mobile-nav" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-30 bg-slate-950/30 lg:hidden" />}
    <aside className={cn('fixed inset-y-0 left-0 z-40 flex flex-col border-r border-[#2d4050] bg-[#172634] text-slate-300 transition-all duration-200 lg:relative lg:z-0 lg:translate-x-0', collapsed ? 'w-[76px]' : 'w-[252px]', mobileOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0')}>
      <div className="flex h-[76px] items-center gap-3 border-b border-[#2d4050] px-5">
        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#f3c44e] text-[#172634]"><Shield size={20} strokeWidth={2.5} /></div>
        {!collapsed && <div className="min-w-0"><p className="text-[15px] font-extrabold tracking-[.12em] text-white">RAKSHA SETU</p><p className="font-mono text-[9px] uppercase tracking-[.16em] text-slate-400">Control center</p></div>}
        <button aria-label="Close mobile navigation" data-testid="button-mobile-nav-close" onClick={() => setMobileOpen(false)} className="ml-auto rounded-md p-1.5 text-slate-400 hover:bg-white/10 lg:hidden"><X size={17} /></button>
      </div>
      <div className="flex-1 overflow-y-auto px-3 py-5 scrollbar-thin">
        {navGroups.map((group) => <div key={group.label} className="mb-6">
          {!collapsed && <p className="mb-2 px-3 font-mono text-[9px] font-medium uppercase tracking-[.16em] text-slate-500">{group.label}</p>}
          <div className="space-y-1">{group.items.map(({ href, label, icon: NavIcon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replace(/\s/g, '-')}`} onClick={() => setMobileOpen(false)} className={cn('group flex items-center gap-3 rounded-lg px-3 py-2.5 text-xs font-semibold transition-colors', location === href ? 'bg-[#f3c44e] text-[#172634]' : 'text-slate-400 hover:bg-white/[.07] hover:text-white', collapsed && 'justify-center px-2')} title={collapsed ? label : undefined}><NavIcon size={17} strokeWidth={location === href ? 2.5 : 1.8} /><span className={cn(collapsed && 'hidden')}>{label}</span>{label === 'Live incidents' && !collapsed && <span className="ml-auto rounded-full bg-red-500 px-1.5 py-0.5 font-mono text-[9px] text-white">5</span>}</Link>)}</div>
        </div>)}
      </div>
      {!collapsed && <div className="mx-3 mb-4 rounded-lg border border-[#385063] bg-[#1d3141] p-3"><div className="flex items-center gap-2"><span className="h-2 w-2 animate-pulse-dot rounded-full bg-emerald-400" /><span className="text-[11px] font-bold text-slate-200">All systems operational</span></div><p className="mt-2 font-mono text-[9px] text-slate-500">Last sync · 08:51:04 IST</p></div>}
      <div className="border-t border-[#2d4050] p-3"><button data-testid="button-collapse-sidebar" onClick={() => setCollapsed(!collapsed)} className="flex w-full items-center justify-center gap-2 rounded-lg px-3 py-2 text-xs text-slate-400 hover:bg-white/[.07] hover:text-white">{collapsed ? <ChevronRight size={16} /> : <><ChevronLeft size={16} /><span>Collapse menu</span></>}</button></div>
    </aside>

    <main className="flex min-w-0 flex-1 flex-col">
      <header className="sticky top-0 z-20 flex min-h-[76px] items-center justify-between gap-4 border-b border-slate-200 bg-white/95 px-4 backdrop-blur md:px-7">
        <div className="flex min-w-0 items-center gap-3">
          <button aria-label="Open navigation" data-testid="button-open-mobile-nav" onClick={() => setMobileOpen(true)} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100 lg:hidden"><Menu size={20} /></button>
          <div className="min-w-0"><h1 data-testid="text-page-title" className="truncate text-lg font-extrabold tracking-tight text-slate-800">{meta.title}</h1><p data-testid="text-page-description" className="hidden truncate text-xs text-slate-500 sm:block">{meta.description}</p></div>
        </div>
        <div className="flex items-center gap-1.5 sm:gap-3">
          <div className={cn('relative hidden items-center rounded-lg border border-slate-200 bg-slate-50 sm:flex', searchOpen ? 'w-64' : 'w-9')}><button aria-label="Toggle search" data-testid="button-toggle-search" onClick={() => { setSearchOpen(!searchOpen); if (searchOpen) setSearch(''); }} className="flex h-9 w-9 shrink-0 items-center justify-center text-slate-500 hover:text-cyan-700"><Search size={16} /></button>{searchOpen && <input autoFocus value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search this workspace" data-testid="input-global-search" className="w-full bg-transparent pr-3 text-xs outline-none placeholder:text-slate-400" />}</div>
          <div className="relative"><button data-testid="button-location-selector" onClick={() => setLocationOpen(!locationOpen)} className="hidden items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 md:flex"><MapPin size={14} className="text-cyan-700" />{selectedLocation}<ChevronDown size={13} /></button>{locationOpen && <div className="absolute right-0 top-11 z-50 w-56 rounded-xl border border-slate-200 bg-white p-1.5 shadow-xl">{['Bengaluru · Central', 'Bengaluru · North', 'Bengaluru · East'].map((name) => <button key={name} data-testid={`button-location-${name.toLowerCase().replace(/ · /g, '-')}`} onClick={() => { setSelectedLocation(name); setLocationOpen(false); pushToast(`Viewing ${name}`, 'info'); }} className={cn('flex w-full items-center justify-between rounded-lg px-3 py-2.5 text-left text-xs hover:bg-slate-50', selectedLocation === name ? 'font-bold text-cyan-700' : 'text-slate-600')}>{name}{selectedLocation === name && <Check size={14} />}</button>)}</div>}</div>
          <div className="relative"><button aria-label="Notifications" data-testid="button-notifications" onClick={() => setNotificationOpen(!notificationOpen)} className="relative rounded-lg p-2 text-slate-500 hover:bg-slate-100"><Bell size={18} />{unread > 0 && <span className="absolute right-1 top-1 h-2 w-2 rounded-full border-2 border-white bg-red-500" />}</button>{notificationOpen && <div className="absolute right-0 top-11 z-50 w-[min(340px,calc(100vw-32px))] rounded-xl border border-slate-200 bg-white shadow-xl"><div className="flex items-center justify-between border-b border-slate-100 px-4 py-3"><div><p className="text-sm font-extrabold">Notifications</p><p className="text-[10px] text-slate-500">{unread} unread updates</p></div><button data-testid="button-mark-notifications-read" onClick={markAllRead} className="text-[10px] font-bold text-cyan-700">Mark all read</button></div>{notifications.map((item) => <button key={item.id} data-testid={`button-notification-${item.id}`} onClick={() => { setReadNotifications([...readNotifications, item.id]); pushToast('Notification opened', 'info'); }} className="flex w-full gap-3 border-b border-slate-100 px-4 py-3 text-left hover:bg-slate-50"><span className={cn('mt-1 h-2 w-2 shrink-0 rounded-full', item.tone === 'critical' ? 'bg-red-500' : item.tone === 'good' ? 'bg-emerald-500' : 'bg-cyan-500')} /><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2 text-xs font-bold"><span className="truncate">{item.title}</span>{!readNotifications.includes(item.id) && <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-cyan-600" />}</span><span className="mt-1 block text-[11px] leading-4 text-slate-500">{item.description}</span><span className="mt-1 block font-mono text-[9px] text-slate-400">{item.time}</span></span></button>)}</div>}</div>
          <div className="relative"><button data-testid="button-profile-menu" onClick={() => setProfileOpen(!profileOpen)} className="flex items-center gap-2 rounded-lg p-1.5 hover:bg-slate-100"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d9e9eb] text-xs font-extrabold text-cyan-800">AK</span><span className="hidden text-left lg:block"><span className="block text-xs font-bold">Anika Kulkarni</span><span className="block font-mono text-[9px] text-slate-500">Operations admin</span></span><ChevronDown size={13} className="hidden text-slate-400 lg:block" /></button>{profileOpen && <div className="absolute right-0 top-11 z-50 w-48 rounded-xl border border-slate-200 bg-white p-1.5 shadow-xl"><button data-testid="button-profile-settings" onClick={() => navigate('/settings')} className="flex w-full items-center gap-2 rounded-lg px-3 py-2.5 text-left text-xs font-semibold hover:bg-slate-50"><Settings size={14} />Control center settings</button><button data-testid="button-profile-lock" onClick={() => { setProfileOpen(false); pushToast('Session remains local and active', 'info'); }} className="flex w-full items-center gap-2 rounded-lg px-3 py-2.5 text-left text-xs font-semibold hover:bg-slate-50"><Shield size={14} />Session status</button></div>}</div>
        </div>
      </header>
      <div className="flex-1 px-4 py-5 md:px-7 md:py-7">{children}</div>
      {toasts.length > 0 && <div className="fixed bottom-5 right-5 z-[60] flex w-[min(340px,calc(100vw-40px))] flex-col gap-2">{toasts.map((toast) => <div key={toast.id} data-testid={`toast-${toast.id}`} className="animate-rise-in flex items-center gap-3 rounded-xl border border-slate-200 bg-white px-4 py-3 text-xs font-bold text-slate-700 shadow-xl"><span className={cn('flex h-6 w-6 shrink-0 items-center justify-center rounded-full', toast.tone === 'warning' ? 'bg-amber-100 text-amber-700' : toast.tone === 'success' ? 'bg-emerald-100 text-emerald-700' : 'bg-cyan-100 text-cyan-700')}>{toast.tone === 'warning' ? <Zap size={13} /> : <Check size={13} />}</span>{toast.message}</div>)}</div>}
    </main>
  </div>;
}

function Overview({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [, setLocation] = useLocation();
  return <div className="mx-auto max-w-[1500px] space-y-6">
    <div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1.5"><span className="h-2 w-2 animate-pulse-dot rounded-full bg-emerald-500" /><span className="font-mono text-[10px] font-medium uppercase tracking-[.12em] text-emerald-700">Live operations · 08:51 IST</span></div><button data-testid="button-refresh-overview" onClick={() => pushToast('Operating picture refreshed', 'success')} className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50"><RefreshCw size={14} />Refresh board</button></div>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Open incidents" value="05" detail="2 require immediate action" icon={Siren} accent="red" trend="down" /><MetricCard label="Avg. response time" value="08:42" detail="Target under 10 minutes" icon={Clock3} accent="teal" trend="up" /><MetricCard label="Units available" value="18 / 24" detail="75% fleet ready to dispatch" icon={Ambulance} accent="blue" /><MetricCard label="Team readiness" value="92%" detail="Across 6 active response teams" icon={Gauge} accent="amber" trend="up" /></div>
    <div className="grid gap-5 xl:grid-cols-[1.4fr_.8fr]">
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-[0_1px_2px_rgba(22,38,58,.03)]"><SectionHeading eyebrow="Priority queue" title="Incidents needing attention" action="View all incidents" onAction={() => setLocation('/incidents')} /><div className="divide-y divide-slate-100">{incidents.slice(0, 4).map((incident) => <button key={incident.id} data-testid={`button-overview-incident-${incident.id}`} onClick={() => setLocation('/incidents')} className="flex w-full items-center gap-3 py-3 text-left hover:bg-slate-50"><span className={cn('h-2 w-2 shrink-0 rounded-full', incident.severity === 'Critical' ? 'bg-red-500' : incident.severity === 'High' ? 'bg-orange-500' : 'bg-amber-500')} /><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] font-medium text-slate-400">{incident.code}</span><StatusBadge label={incident.severity} tone={incident.severity.toLowerCase()} /></span><span className="mt-1 block truncate text-xs font-bold text-slate-700">{incident.type} · {incident.location}</span></span><span className="hidden text-right sm:block"><span className="block font-mono text-[10px] text-slate-500">{incident.reportedAt}</span><span className="mt-1 block text-[10px] text-slate-400">{incident.assignments.length} units</span></span><ChevronRight size={15} className="text-slate-300" /></button>)}</div></section>
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-[0_1px_2px_rgba(22,38,58,.03)]"><SectionHeading eyebrow="Readiness snapshot" title="Resource posture" action="Open fleet" onAction={() => setLocation('/vehicles')} /><div className="space-y-5"><ReadinessBar label="Ambulance fleet" value={86} detail="6 of 7 ready" color="bg-cyan-600" /><ReadinessBar label="Patrol vehicles" value={78} detail="7 of 9 ready" color="bg-amber-500" /><ReadinessBar label="Response teams" value={92} detail="5 of 6 available" color="bg-emerald-500" /></div><div className="mt-6 grid grid-cols-3 gap-2 border-t border-slate-100 pt-4 text-center"><div><p className="font-mono text-lg font-medium">03</p><p className="text-[10px] text-slate-500">At scene</p></div><div><p className="font-mono text-lg font-medium">04</p><p className="text-[10px] text-slate-500">En route</p></div><div><p className="font-mono text-lg font-medium text-orange-600">01</p><p className="text-[10px] text-slate-500">Maintenance</p></div></div></section>
    </div>
    <div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]">
      <section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Coverage" title="Zone activity" /><div className="relative h-56 overflow-hidden rounded-lg border border-slate-200 bg-[#e7eef0]"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: 'linear-gradient(#b5c9ce 1px, transparent 1px), linear-gradient(90deg, #b5c9ce 1px, transparent 1px)', backgroundSize: '34px 34px' }} /><div className="absolute left-[22%] top-[28%] h-20 w-32 rotate-12 border-2 border-cyan-700/40 bg-cyan-700/10" /><div className="absolute left-[55%] top-[18%] h-24 w-36 -rotate-6 border-2 border-amber-600/35 bg-amber-500/10" /><div className="absolute bottom-[18%] left-[40%] h-16 w-48 rotate-3 border-2 border-slate-500/30 bg-slate-400/10" />{[['North', '26%', '25%', 'bg-red-500'], ['Central', '53%', '58%', 'bg-cyan-600'], ['East', '72%', '34%', 'bg-amber-500'], ['West', '29%', '68%', 'bg-emerald-500']].map(([zone, left, top, dot]) => <div key={zone} className="absolute" style={{ left, top }}><span className={cn('block h-3 w-3 rounded-full border-2 border-white shadow-sm', dot)} /><span className="absolute left-4 top-[-3px] whitespace-nowrap rounded bg-white/90 px-1.5 py-0.5 font-mono text-[9px] font-medium text-slate-600 shadow-sm">{zone}</span></div>)}</div><div className="mt-3 flex flex-wrap gap-4 text-[10px] text-slate-500"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-red-500" />Priority incident</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-cyan-600" />Active response</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-emerald-500" />Available coverage</span></div></section>
      <section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Activity stream" title="Command log" action="Incident history" onAction={() => setLocation('/history')} /><div className="space-y-4">{[['08:49', 'AMB-07 dispatched', 'INC-2481 · North corridor', 'cyan'], ['08:44', 'Incident accepted', 'INC-2480 · Response 02', 'amber'], ['08:38', 'Zone status updated', 'East district · monitoring', 'slate'], ['08:32', 'Hospital capacity synced', 'Suryodaya Medical Centre', 'emerald'], ['08:21', 'Diversion confirmed', 'Lake Road underpass', 'slate']].map(([time, event, detail, tone]) => <div key={time + event} className="flex gap-3"><span className={cn('mt-1 h-2 w-2 shrink-0 rounded-full', tone === 'cyan' ? 'bg-cyan-500' : tone === 'amber' ? 'bg-amber-500' : tone === 'emerald' ? 'bg-emerald-500' : 'bg-slate-300')} /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><p className="truncate text-xs font-bold text-slate-700">{event}</p><span className="font-mono text-[9px] text-slate-400">{time}</span></div><p className="mt-0.5 truncate text-[11px] text-slate-500">{detail}</p></div></div>)}</div></section>
    </div>
  </div>;
}

function ReadinessBar({ label, value, detail, color }: { label: string; value: number; detail: string; color: string }) {
  return <div><div className="mb-2 flex justify-between text-xs"><span className="font-bold text-slate-700">{label}</span><span className="font-mono text-slate-500">{detail}</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={cn('h-full rounded-full transition-all', color)} style={{ width: `${value}%` }} /></div></div>;
}

function IncidentsPage({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [selected, setSelected] = useState<Incident | null>(null);
  const [filter, setFilter] = useState('All');
  const [query, setQuery] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const filtered = incidents.filter((incident) => (filter === 'All' || incident.status === filter || incident.severity === filter) && `${incident.code} ${incident.type} ${incident.location}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="mx-auto max-w-[1500px] space-y-5">
    <div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="flex items-center gap-2 rounded-full border border-red-200 bg-red-50 px-3 py-1.5 font-mono text-[10px] font-medium uppercase tracking-[.12em] text-red-700"><span className="h-1.5 w-1.5 animate-pulse-dot rounded-full bg-red-500" />5 open incidents</span><span className="hidden text-xs text-slate-500 sm:inline">Updated moments ago</span></div><div className="flex gap-2"><button data-testid="button-toggle-incident-filters" onClick={() => setShowFilters(!showFilters)} className={cn('inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold', showFilters ? 'border-cyan-300 bg-cyan-50 text-cyan-700' : 'border-slate-200 bg-white text-slate-600')}><Filter size={14} />Filters</button><button data-testid="button-log-incident" onClick={() => pushToast('Local incident intake opened', 'info')} className="inline-flex items-center gap-2 rounded-lg bg-[#172634] px-3 py-2 text-xs font-bold text-white hover:bg-[#23394a]"><Siren size={14} />Log incident</button></div></div>
    {showFilters && <div className="animate-rise-in flex flex-wrap items-center gap-2 rounded-xl border border-slate-200 bg-white p-3"><span className="mr-1 text-[10px] font-bold uppercase tracking-[.1em] text-slate-400">Show</span>{['All', 'Critical', 'High', 'Active', 'Dispatched', 'Monitoring', 'Resolved'].map((item) => <button key={item} data-testid={`button-incident-filter-${item.toLowerCase()}`} onClick={() => setFilter(item)} className={cn('rounded-full border px-3 py-1.5 text-[10px] font-bold', filter === item ? 'border-cyan-600 bg-cyan-700 text-white' : 'border-slate-200 text-slate-600 hover:border-cyan-300')}>{item}</button>)}<div className="ml-auto flex items-center gap-2 rounded-lg border border-slate-200 px-2.5"><Search size={13} className="text-slate-400" /><input data-testid="input-incident-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search incidents" className="w-40 bg-transparent py-1.5 text-xs outline-none" /></div></div>}
    <div className="grid gap-5 xl:grid-cols-[1fr_370px]"><section className="min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="border-b border-slate-100 bg-slate-50/70"><tr>{['Incident', 'Severity', 'Location', 'Status', 'Units', 'Reported', ''].map((heading) => <th key={heading} className="px-4 py-3 font-mono text-[9px] font-medium uppercase tracking-[.12em] text-slate-400">{heading}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{filtered.map((incident) => <tr key={incident.id} data-testid={`row-incident-${incident.id}`} onClick={() => setSelected(incident)} className={cn('cursor-pointer transition-colors hover:bg-cyan-50/40', selected?.id === incident.id && 'bg-cyan-50/70')}><td className="px-4 py-3"><div className="flex items-center gap-2.5"><span className={cn('h-2 w-2 rounded-full', incident.severity === 'Critical' ? 'bg-red-500' : incident.severity === 'High' ? 'bg-orange-500' : 'bg-amber-500')} /><div><p className="font-mono text-[10px] font-medium text-cyan-700">{incident.code}</p><p className="mt-0.5 text-xs font-bold text-slate-700">{incident.type}</p></div></div></td><td className="px-4 py-3"><StatusBadge label={incident.severity} tone={incident.severity.toLowerCase()} /></td><td className="px-4 py-3"><p className="max-w-[210px] truncate text-xs font-semibold text-slate-700">{incident.location}</p><p className="mt-0.5 text-[10px] text-slate-400">{incident.zone}</p></td><td className="px-4 py-3"><StatusBadge label={incident.status} tone={incident.status.toLowerCase()} /></td><td className="px-4 py-3"><span className="font-mono text-xs text-slate-600">{incident.assignments.length.toString().padStart(2, '0')}</span></td><td className="px-4 py-3 font-mono text-[10px] text-slate-500">{incident.reportedAt}</td><td className="px-4 py-3"><ChevronRight size={15} className="text-slate-300" /></td></tr>)}</tbody></table></div>{filtered.length === 0 && <div className="p-4"><EmptyState title="No incidents match" detail="Try changing the queue filter or search term." icon={Siren} /></div>}</section>{selected ? <IncidentDetail incident={selected} onClose={() => setSelected(null)} pushToast={pushToast} /> : <div className="hidden xl:block"><EmptyState title="Select an incident" detail="Choose a row to inspect the timeline, caller detail and current assignments." icon={MapPin} /></div>}</div>
  </div>;
}

function IncidentDetail({ incident, onClose, pushToast }: { incident: Incident; onClose: () => void; pushToast: AppProps['pushToast'] }) {
  const [expanded, setExpanded] = useState(false);
  return <aside data-testid={`panel-incident-${incident.id}`} className="animate-rise-in rounded-xl border border-slate-200 bg-white p-5 shadow-[0_8px_24px_rgba(22,38,58,.05)]"><div className="flex items-start justify-between gap-3"><div><p className="font-mono text-[10px] font-medium tracking-[.12em] text-cyan-700">{incident.code}</p><h2 className="mt-1 text-lg font-extrabold tracking-tight">{incident.type}</h2></div><button aria-label="Close incident detail" data-testid="button-close-incident-detail" onClick={onClose} className="rounded-md p-1.5 text-slate-400 hover:bg-slate-100"><X size={16} /></button></div><div className="mt-4 flex flex-wrap gap-2"><StatusBadge label={incident.severity} tone={incident.severity.toLowerCase()} /><StatusBadge label={incident.status} tone={incident.status.toLowerCase()} /></div><div className="mt-5 space-y-4 border-t border-slate-100 pt-4"><div className="flex gap-3"><MapPin size={16} className="mt-0.5 shrink-0 text-cyan-700" /><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Location</p><p className="mt-1 text-xs font-bold">{incident.location}</p><p className="mt-0.5 text-[10px] text-slate-500">{incident.zone}</p></div></div><div className="flex gap-3"><UserRound size={16} className="mt-0.5 shrink-0 text-cyan-700" /><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Caller</p><p className="mt-1 text-xs font-bold">{incident.caller}</p><p className="mt-0.5 font-mono text-[10px] text-slate-500">{incident.callerPhone}</p></div></div><div className="flex gap-3"><Clock3 size={16} className="mt-0.5 shrink-0 text-cyan-700" /><div><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Reported</p><p className="mt-1 font-mono text-xs font-bold">{incident.reportedAt} IST</p><p className="mt-0.5 text-[10px] text-slate-500">Last updated {incident.updatedAt}</p></div></div></div><div className="mt-5 rounded-lg bg-slate-50 p-3"><p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Situation note</p><p className={cn('mt-1 text-xs leading-5 text-slate-600', !expanded && 'line-clamp-2')}>{incident.summary}</p><button data-testid="button-toggle-incident-summary" onClick={() => setExpanded(!expanded)} className="mt-2 text-[10px] font-bold text-cyan-700">{expanded ? 'Show less' : 'Read full note'}</button></div><div className="mt-5"><p className="mb-2 text-[10px] font-bold uppercase tracking-wider text-slate-400">Assigned units</p><div className="space-y-2">{incident.assignments.map((unit) => <div key={unit} className="flex items-center justify-between rounded-lg border border-slate-100 px-3 py-2"><span className="font-mono text-xs font-medium">{unit}</span><span className="text-[10px] text-emerald-600">Connected</span></div>)}</div></div><div className="mt-5 grid grid-cols-2 gap-2"><button data-testid="button-incident-acknowledge" onClick={() => pushToast(`${incident.code} acknowledged by control`, 'success')} className="rounded-lg bg-cyan-700 px-3 py-2.5 text-xs font-bold text-white hover:bg-cyan-800">Acknowledge</button><button data-testid="button-incident-reassign" onClick={() => pushToast('Reassignment board opened', 'info')} className="rounded-lg border border-slate-200 px-3 py-2.5 text-xs font-bold text-slate-600 hover:bg-slate-50">Reassign units</button></div></aside>;
}

type ResourceRow = { [key: string]: string | number };

function ResourceTablePage({ kind, pushToast }: { kind: 'vehicles' | 'drivers'; pushToast: AppProps['pushToast'] }) {
  const isVehicles = kind === 'vehicles';
  const source = (isVehicles ? vehicles : drivers) as ResourceRow[];
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('All');
  const [selected, setSelected] = useState<string | null>(null);
  const filtered = source.filter((item) => {
    const searchable = isVehicles ? `${item.id} ${item.name} ${item.type} ${item.location} ${item.driver}` : `${item.id} ${item.name} ${item.role} ${item.vehicle} ${item.zone}`;
    return (filter === 'All' || String(item.status) === filter) && searchable.toLowerCase().includes(query.toLowerCase());
  });
  const statuses = ['All', ...Array.from(new Set(source.map((item) => String(item.status))))];
  return <div className="mx-auto max-w-[1500px] space-y-5">
    <div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs text-slate-500">{isVehicles ? '07 registered assets' : '07 rostered drivers'} · Local shift board</p></div><button data-testid={`button-${kind}-export`} onClick={() => pushToast(`${isVehicles ? 'Fleet' : 'Roster'} report prepared locally`, 'success')} className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50"><Download size={14} />Export report</button></div>
    <div className="flex flex-wrap gap-2 rounded-xl border border-slate-200 bg-white p-3"><div className="flex min-w-[210px] flex-1 items-center gap-2 rounded-lg border border-slate-200 px-3"><Search size={14} className="text-slate-400" /><input data-testid={`input-${kind}-search`} value={query} onChange={(event) => setQuery(event.target.value)} placeholder={isVehicles ? 'Search by asset, type or zone' : 'Search by name, role or assignment'} className="w-full bg-transparent py-2 text-xs outline-none" /></div><div className="flex items-center gap-1 overflow-x-auto">{statuses.map((status) => <button key={status} data-testid={`button-${kind}-filter-${status.toLowerCase().replace(/\s/g, '-')}`} onClick={() => setFilter(status)} className={cn('whitespace-nowrap rounded-lg px-3 py-2 text-[10px] font-bold', filter === status ? 'bg-[#172634] text-white' : 'text-slate-500 hover:bg-slate-100')}>{status}</button>)}</div></div>
    <div className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="border-b border-slate-100 bg-slate-50/70"><tr>{(isVehicles ? ['Asset', 'Type', 'Status', 'Location', 'Driver / team', 'Readiness', ''] : ['Driver', 'Role', 'Status', 'Shift', 'Vehicle', 'Zone', '']).map((heading) => <th key={heading} className="px-4 py-3 font-mono text-[9px] font-medium uppercase tracking-[.12em] text-slate-400">{heading}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{filtered.map((item) => isVehicles ? <tr key={String(item.id)} data-testid={`row-vehicle-${item.id}`} onClick={() => setSelected(String(item.id))} className={cn('cursor-pointer hover:bg-cyan-50/40', selected === String(item.id) && 'bg-cyan-50/70')}><td className="px-4 py-3"><p className="font-mono text-xs font-medium text-cyan-700">{item.id}</p><p className="mt-0.5 text-xs font-bold text-slate-700">{item.name}</p></td><td className="px-4 py-3 text-xs text-slate-600">{item.type}</td><td className="px-4 py-3"><StatusBadge label={String(item.status)} tone={String(item.status).toLowerCase()} /></td><td className="px-4 py-3 text-xs font-semibold text-slate-600">{item.location}</td><td className="px-4 py-3"><p className="text-xs font-semibold text-slate-700">{item.driver}</p><p className="mt-0.5 font-mono text-[10px] text-slate-400">{item.team}</p></td><td className="px-4 py-3"><div className="flex items-center gap-2"><div className="h-1.5 w-16 overflow-hidden rounded-full bg-slate-100"><div className={cn('h-full rounded-full', Number(item.readiness) > 80 ? 'bg-emerald-500' : 'bg-orange-500')} style={{ width: `${item.readiness}%` }} /></div><span className="font-mono text-[10px]">{item.readiness}%</span></div></td><td className="px-4 py-3"><ChevronRight size={15} className="text-slate-300" /></td></tr> : <tr key={String(item.id)} data-testid={`row-driver-${item.id}`} onClick={() => setSelected(String(item.id))} className={cn('cursor-pointer hover:bg-cyan-50/40', selected === String(item.id) && 'bg-cyan-50/70')}><td className="px-4 py-3"><div className="flex items-center gap-2.5"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d9e9eb] text-[10px] font-extrabold text-cyan-800">{item.initials}</span><div><p className="text-xs font-bold text-slate-700">{item.name}</p><p className="mt-0.5 font-mono text-[9px] text-slate-400">{item.id}</p></div></div></td><td className="px-4 py-3 text-xs text-slate-600">{item.role}</td><td className="px-4 py-3"><StatusBadge label={String(item.status)} tone={String(item.status).toLowerCase()} /></td><td className="px-4 py-3 font-mono text-[10px] text-slate-500">{item.shift}</td><td className="px-4 py-3 font-mono text-xs text-cyan-700">{item.vehicle}</td><td className="px-4 py-3 text-xs text-slate-600">{item.zone}</td><td className="px-4 py-3"><ChevronRight size={15} className="text-slate-300" /></td></tr>)}</tbody></table></div>{filtered.length === 0 && <div className="p-4"><EmptyState title={`No ${kind} found`} detail="Try a different search or availability filter." /></div>}</div>
    {selected && <DetailDrawer kind={kind} id={selected} onClose={() => setSelected(null)} pushToast={pushToast} />}
  </div>;
}

function DetailDrawer({ kind, id, onClose, pushToast }: { kind: 'vehicles' | 'drivers'; id: string; onClose: () => void; pushToast: AppProps['pushToast'] }) {
  const item = (kind === 'vehicles' ? vehicles.find((entry) => entry.id === id) : drivers.find((entry) => entry.id === id)) as ResourceRow | undefined;
  if (!item) return null;
  return <div className="fixed inset-0 z-50 flex justify-end"><button data-testid="button-close-resource-overlay" aria-label="Close resource detail" onClick={onClose} className="absolute inset-0 bg-slate-950/25" /><aside data-testid={`drawer-${kind}-${id}`} className="animate-rise-in relative h-full w-full max-w-md overflow-y-auto border-l border-slate-200 bg-white p-6 shadow-2xl"><button data-testid="button-close-resource-drawer" onClick={onClose} className="absolute right-5 top-5 rounded-lg p-1.5 text-slate-400 hover:bg-slate-100"><X size={17} /></button><p className="font-mono text-[10px] uppercase tracking-[.14em] text-cyan-700">{id}</p><h2 className="mt-2 text-xl font-extrabold">{item.name}</h2><p className="mt-1 text-xs text-slate-500">{kind === 'vehicles' ? item.type : item.role}</p><div className="mt-5"><StatusBadge label={String(item.status)} tone={String(item.status).toLowerCase()} /></div><div className="mt-7 space-y-4">{(kind === 'vehicles' ? [['Current location', item.location], ['Assigned driver', item.driver], ['Response team', item.team], ['Fuel level', `${item.fuel}%`], ['Last service', item.lastService], ['Dispatch ETA', item.eta]] : [['Shift', item.shift], ['Vehicle', item.vehicle], ['Coverage zone', item.zone], ['Contact', item.contact], ['Duty hours', item.hours]]).map(([label, value]) => <div key={String(label)} className="flex items-center justify-between border-b border-slate-100 pb-3"><span className="text-xs text-slate-500">{label}</span><span className="text-right text-xs font-bold text-slate-700">{value}</span></div>)}</div><div className="mt-8 grid grid-cols-2 gap-2"><button data-testid="button-resource-contact" onClick={() => pushToast('Contact card copied to local clipboard view', 'success')} className="inline-flex items-center justify-center gap-2 rounded-lg bg-cyan-700 px-3 py-2.5 text-xs font-bold text-white"><Phone size={14} />Contact</button><button data-testid="button-resource-update" onClick={() => pushToast('Update form opened for review', 'info')} className="rounded-lg border border-slate-200 px-3 py-2.5 text-xs font-bold text-slate-600">Update record</button></div></aside></div>;
}

function ServicesPage({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [tab, setTab] = useState<'Ambulances' | 'Hospitals' | 'Police stations'>('Ambulances');
  const data = (tab === 'Ambulances' ? ambulances : tab === 'Hospitals' ? hospitals : policeStations) as Array<{ [key: string]: string }>;
  return <div className="mx-auto max-w-[1500px] space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs text-slate-500">Connected capacity directory · Last verified 08:47 IST</p></div><button data-testid="button-sync-services" onClick={() => pushToast('Service directory synced locally', 'success')} className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50"><RefreshCw size={14} />Sync directory</button></div><div className="flex gap-1 rounded-xl border border-slate-200 bg-white p-1.5">{(['Ambulances', 'Hospitals', 'Police stations'] as const).map((item) => <button key={item} data-testid={`button-services-tab-${item.toLowerCase().replace(/\s/g, '-')}`} onClick={() => setTab(item)} className={cn('flex-1 rounded-lg px-3 py-2.5 text-xs font-bold', tab === item ? 'bg-[#172634] text-white' : 'text-slate-500 hover:bg-slate-50')}>{item}<span className="ml-2 font-mono text-[10px] opacity-60">{item === 'Ambulances' ? ambulances.length : item === 'Hospitals' ? hospitals.length : policeStations.length}</span></button>)}</div><section className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto">{tab === 'Ambulances' ? <table className="w-full min-w-[750px] text-left"><ServiceHead labels={['Unit', 'Capability', 'Status', 'Location', 'ETA', 'Crew', '']} /><tbody className="divide-y divide-slate-100">{ambulances.map((item) => <tr key={item.id} data-testid={`row-ambulance-${item.id}`} className="hover:bg-slate-50"><td className="px-4 py-4"><p className="font-mono text-xs font-medium text-cyan-700">{item.id}</p><p className="mt-1 text-xs font-bold">{item.facility}</p></td><td className="px-4 py-4 text-xs text-slate-600">{item.capability}</td><td className="px-4 py-4"><StatusBadge label={item.status} tone={item.status.toLowerCase()} /></td><td className="px-4 py-4 text-xs text-slate-600">{item.location}</td><td className="px-4 py-4 font-mono text-xs">{item.eta}</td><td className="px-4 py-4 text-xs text-slate-600">{item.crew}</td><td className="px-4 py-4"><button data-testid={`button-contact-ambulance-${item.id}`} onClick={() => pushToast(`${item.id} contact card opened`, 'info')} className="rounded-md p-1.5 text-cyan-700 hover:bg-cyan-50"><Phone size={15} /></button></td></tr>)}</tbody></table> : <table className="w-full min-w-[680px] text-left"><ServiceHead labels={tab === 'Hospitals' ? ['Facility', 'Type', 'Status', 'Distance', 'Trauma beds', 'Contact'] : ['Station', 'Type', 'Status', 'Distance', 'Unit capacity', '']} /><tbody className="divide-y divide-slate-100">{data.map((item) => <tr key={item.id} data-testid={`row-service-${item.id}`} className="hover:bg-slate-50"><td className="px-4 py-4"><p className="text-xs font-bold">{item.name}</p><p className="mt-1 font-mono text-[9px] text-cyan-700">{item.id}</p></td><td className="px-4 py-4 text-xs text-slate-600">{item.type}</td><td className="px-4 py-4"><StatusBadge label={item.status} tone={item.status.toLowerCase()} /></td><td className="px-4 py-4 font-mono text-xs text-slate-600">{item.distance}</td><td className="px-4 py-4 text-xs font-semibold text-slate-600">{tab === 'Hospitals' ? item.beds : item.unit}</td><td className="px-4 py-4 text-xs text-slate-500">{tab === 'Hospitals' ? item.contact : <button data-testid={`button-contact-station-${item.id}`} onClick={() => pushToast(`${item.name} contact card opened`, 'info')} className="rounded-md p-1.5 text-cyan-700 hover:bg-cyan-50"><Phone size={15} /></button>}</td></tr>)}</tbody></table>}</div></section></div>;
}

function ServiceHead({ labels }: { labels: string[] }) {
  return <thead className="border-b border-slate-100 bg-slate-50/70"><tr>{labels.map((label) => <th key={label} className="px-4 py-3 font-mono text-[9px] font-medium uppercase tracking-[.12em] text-slate-400">{label}</th>)}</tr></thead>;
}

function TeamsPage({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [filter, setFilter] = useState('All');
  const statuses = ['All', 'Available', 'Deployed', 'On scene', 'Monitoring', 'Off duty'];
  const list = responseTeams.filter((team) => filter === 'All' || team.status === filter);
  return <div className="mx-auto max-w-[1500px] space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="font-mono text-xs font-medium text-slate-600">06 teams registered</span><span className="h-1 w-1 rounded-full bg-slate-300" /><span className="font-mono text-xs text-emerald-600">03 available now</span></div><button data-testid="button-team-broadcast" onClick={() => pushToast('Broadcast composer opened', 'info')} className="inline-flex items-center gap-2 rounded-lg bg-[#172634] px-3 py-2 text-xs font-bold text-white"><Send size={14} />Broadcast update</button></div><div className="flex gap-1 overflow-x-auto rounded-xl border border-slate-200 bg-white p-1.5">{statuses.map((status) => <button key={status} data-testid={`button-team-filter-${status.toLowerCase().replace(/\s/g, '-')}`} onClick={() => setFilter(status)} className={cn('whitespace-nowrap rounded-lg px-3 py-2 text-[10px] font-bold', filter === status ? 'bg-[#172634] text-white' : 'text-slate-500 hover:bg-slate-50')}>{status}</button>)}</div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{list.map((team, index) => <article key={team.id} data-testid={`card-team-${team.id}`} className={cn('animate-rise-in rounded-xl border border-slate-200 bg-white p-5', `delay-${Math.min(index + 1, 4)}`)}><div className="flex items-start justify-between gap-3"><div><p className="font-mono text-[10px] text-cyan-700">{team.id}</p><h2 className="mt-1 text-sm font-extrabold">{team.name}</h2></div><StatusBadge label={team.status} tone={team.status.toLowerCase()} /></div><p className="mt-4 text-xs font-semibold text-slate-600">{team.specialty}</p><div className="mt-5 space-y-3 border-t border-slate-100 pt-4"><div className="flex justify-between text-xs"><span className="text-slate-500">Team lead</span><span className="font-bold">{team.lead}</span></div><div className="flex justify-between text-xs"><span className="text-slate-500">Current position</span><span className="max-w-[170px] truncate text-right font-bold">{team.location}</span></div><div><div className="mb-1.5 flex justify-between text-[10px]"><span className="text-slate-500">Readiness</span><span className="font-mono">{team.readiness}%</span></div><ReadinessBar label="" value={team.readiness} detail={`${team.members} members`} color={team.readiness > 90 ? 'bg-emerald-500' : 'bg-amber-500'} /></div></div><button data-testid={`button-team-contact-${team.id}`} onClick={() => pushToast(`${team.name} update channel opened`, 'info')} className="mt-5 flex w-full items-center justify-center gap-2 rounded-lg border border-slate-200 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50"><MessageSquare size={14} />Open team channel</button></article>)}</div>{list.length === 0 && <EmptyState title="No teams in this state" detail="Change the availability filter to see other response teams." icon={Users} />}</div>;
}

function HistoryPage({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [query, setQuery] = useState('');
  const [severity, setSeverity] = useState('All');
  const list = history.filter((item) => (severity === 'All' || item.severity === severity) && `${item.id} ${item.type} ${item.location}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="mx-auto max-w-[1500px] space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-slate-500">Showing the last 30 days · 184 closed incidents</p><button data-testid="button-export-history" onClick={() => pushToast('History export prepared locally', 'success')} className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600"><Download size={14} />Export log</button></div><div className="flex flex-wrap gap-2 rounded-xl border border-slate-200 bg-white p-3"><div className="flex min-w-[220px] flex-1 items-center gap-2 rounded-lg border border-slate-200 px-3"><Search size={14} className="text-slate-400" /><input data-testid="input-history-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search past incidents" className="w-full bg-transparent py-2 text-xs outline-none" /></div>{['All', 'Critical', 'High', 'Moderate', 'Low'].map((item) => <button key={item} data-testid={`button-history-filter-${item.toLowerCase()}`} onClick={() => setSeverity(item)} className={cn('rounded-lg px-3 py-2 text-[10px] font-bold', severity === item ? 'bg-[#172634] text-white' : 'text-slate-500 hover:bg-slate-100')}>{item}</button>)}</div><section className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[750px] text-left"><ServiceHead labels={['Incident', 'Type', 'Location', 'Severity', 'Duration', 'Outcome', 'Closed']} /><tbody className="divide-y divide-slate-100">{list.map((item) => <tr key={item.id} data-testid={`row-history-${item.id}`} className="hover:bg-slate-50"><td className="px-4 py-4 font-mono text-xs font-medium text-cyan-700">{item.id}</td><td className="px-4 py-4 text-xs font-bold">{item.type}</td><td className="px-4 py-4 text-xs text-slate-600">{item.location}</td><td className="px-4 py-4"><StatusBadge label={item.severity} tone={item.severity.toLowerCase()} /></td><td className="px-4 py-4 font-mono text-xs text-slate-600">{item.duration}</td><td className="px-4 py-4"><StatusBadge label={item.outcome} tone={item.outcome === 'Resolved' ? 'resolved' : 'transferred'} /></td><td className="px-4 py-4 font-mono text-[10px] text-slate-500">{item.closed}</td></tr>)}</tbody></table></div>{list.length === 0 && <div className="p-4"><EmptyState title="No matching history" detail="No completed incident matches the current filters." icon={FileClock} /></div>}</section></div>;
}

function AnalyticsPage() {
  const bars = [62, 74, 58, 83, 70, 91, 78, 68, 86, 94, 72, 89];
  const [range, setRange] = useState('Last 30 days');
  return <div className="mx-auto max-w-[1500px] space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-slate-500">{range === 'Last 30 days' ? '01 Jun — 30 Jun 2024' : '24 Jun — 30 Jun 2024'} · Compared with previous period</p><button data-testid="button-analytics-range" onClick={() => setRange(range === 'Last 30 days' ? 'Last 7 days' : 'Last 30 days')} className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold text-slate-600"><SlidersHorizontal size={14} />{range}<ChevronDown size={13} /></button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Incidents handled" value="184" detail="+12.4% from May" icon={Siren} accent="red" trend="up" /><MetricCard label="Median response" value="08:42" detail="1m 18s faster than target" icon={Clock3} accent="teal" trend="up" /><MetricCard label="Resolution rate" value="91.8%" detail="169 incidents closed" icon={CheckCircle2} accent="blue" trend="up" /><MetricCard label="Hospital transfers" value="37" detail="20.1% of all incidents" icon={HeartPulse} accent="amber" /></div><div className="grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Response performance" title="Median response time by day" /><div className="flex h-64 items-end gap-2 border-b border-l border-slate-200 px-4 pb-0 pt-6 sm:gap-4">{bars.map((height, index) => <div key={index} className="group flex flex-1 flex-col items-center justify-end gap-2"><span className="hidden font-mono text-[9px] text-slate-400 group-hover:block">{Math.round(12 - height / 14)}m</span><div className={cn('w-full rounded-t-sm transition-all group-hover:bg-cyan-700', height > 85 ? 'bg-amber-400' : 'bg-cyan-600')} style={{ height: `${height}%` }} /><span className="font-mono text-[9px] text-slate-400">{index + 1}</span></div>)}</div><div className="mt-4 flex items-center gap-5 text-[10px] text-slate-500"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-cyan-600" />Within target</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-amber-400" />Above target</span></div></section><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Incident mix" title="By category" /><div className="space-y-4">{[['Medical emergency', 38, 'bg-red-500'], ['Road incident', 25, 'bg-cyan-600'], ['Fire & hazard', 17, 'bg-amber-500'], ['Public safety', 12, 'bg-emerald-500'], ['Other', 8, 'bg-slate-400']].map(([label, value, color]) => <div key={label as string}><div className="mb-1.5 flex justify-between text-xs"><span className="font-semibold text-slate-600">{label}</span><span className="font-mono text-[10px] text-slate-500">{value}%</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className={cn('h-full rounded-full', color as string)} style={{ width: `${value}%` }} /></div></div>)}</div><div className="mt-7 rounded-lg bg-slate-50 p-3 text-xs leading-5 text-slate-600"><Sparkles size={14} className="mb-1 text-amber-500" /><b>Signal:</b> medical incidents are arriving 8% earlier in the morning window. Central district coverage remains stable.</div></section></div></div>;
}

function DemoPage({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [running, setRunning] = useState(false);
  const [step, setStep] = useState(0);
  const steps = [{ time: '00:00', title: 'Incoming report', detail: 'Multi-vehicle collision reported at NH-48, Sector 18 flyover.', icon: Phone }, { time: '00:18', title: 'Triage complete', detail: 'Critical severity confirmed. Extrication support requested.', icon: Stethoscope }, { time: '01:04', title: 'Units assigned', detail: 'AMB-07, PAT-12 and Response 04 acknowledged dispatch.', icon: Ambulance }, { time: '04:12', title: 'Arrival checkpoint', detail: 'First unit on scene. Hospital routing recommendation ready.', icon: CheckCircle2 }];
  const advance = () => { if (step < steps.length - 1) { setStep(step + 1); pushToast(`Scenario advanced to ${steps[step + 1].title}`, 'info'); } else { setRunning(false); pushToast('Scenario drill completed', 'success'); } };
  return <div className="mx-auto max-w-[1100px] space-y-5"><div className="rounded-xl border border-amber-200 bg-[#fff8e3] p-5"><div className="flex items-start gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[#f3c44e] text-[#172634]"><Radio size={20} /></div><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.14em] text-amber-800">Local-only training tool</p><h2 className="mt-1 text-base font-extrabold text-[#172634]">Run a response scenario</h2><p className="mt-1 max-w-2xl text-xs leading-5 text-amber-900/70">This simulator changes only the local display state. It never calls emergency services, sends messages or contacts external systems.</p></div></div></div><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Scenario library" title="Select a drill" /><button data-testid="button-select-demo-collision" onClick={() => { setStep(0); setRunning(false); pushToast('Collision response drill selected', 'info'); }} className="w-full rounded-xl border-2 border-cyan-600 bg-cyan-50/60 p-4 text-left"><div className="flex items-center justify-between"><span className="font-mono text-[10px] font-bold text-cyan-700">SCN-001</span><StatusBadge label="Critical" tone="critical" /></div><p className="mt-3 text-sm font-extrabold">Multi-vehicle collision</p><p className="mt-1 text-xs leading-5 text-slate-500">NH-48 · Sector 18 flyover · trauma and extrication pathway</p></button><button data-testid="button-select-demo-fire" onClick={() => { setStep(0); setRunning(false); pushToast('Fire response drill selected', 'info'); }} className="mt-3 w-full rounded-xl border border-slate-200 p-4 text-left hover:border-cyan-300"><div className="flex items-center justify-between"><span className="font-mono text-[10px] font-bold text-slate-500">SCN-002</span><StatusBadge label="Moderate" tone="moderate" /></div><p className="mt-3 text-sm font-extrabold">Commercial fire alarm</p><p className="mt-1 text-xs leading-5 text-slate-500">Crescent Tech Park · evacuation and verification pathway</p></button><div className="mt-5 border-t border-slate-100 pt-4"><button data-testid="button-reset-demo" onClick={() => { setStep(0); setRunning(false); pushToast('Scenario reset', 'info'); }} className="flex items-center gap-2 text-xs font-bold text-slate-500 hover:text-slate-800"><RefreshCw size={13} />Reset simulator</button></div></section><section className="rounded-xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.14em] text-cyan-700">Playback timeline</p><h2 className="mt-1 text-base font-extrabold">Collision response drill</h2></div><span className="font-mono text-xs text-slate-500">{steps[step].time}</span></div><div className="relative mt-7 space-y-0">{steps.map((item, index) => { const StepIcon = item.icon; return <div key={item.title} className="relative flex gap-4 pb-7 last:pb-0"><div className="relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 bg-white" style={{ borderColor: index <= step ? '#0e7d8b' : '#d7e0e5', color: index <= step ? '#0e7d8b' : '#9aa9b3' }}><StepIcon size={14} /></div>{index < steps.length - 1 && <span className={cn('absolute left-[15px] top-8 h-full w-0.5', index < step ? 'bg-cyan-600' : 'bg-slate-200')} /> }<div className="min-w-0 pt-0.5"><div className="flex items-center gap-2"><p className={cn('text-xs font-bold', index <= step ? 'text-slate-800' : 'text-slate-400')}>{item.title}</p><span className="font-mono text-[9px] text-slate-400">{item.time}</span></div><p className={cn('mt-1 text-xs leading-5', index <= step ? 'text-slate-500' : 'text-slate-400')}>{item.detail}</p></div></div>; })}</div><div className="mt-7 flex gap-2 border-t border-slate-100 pt-5">{!running && step === 0 ? <button data-testid="button-start-demo" onClick={() => { setRunning(true); pushToast('Scenario started locally', 'info'); }} className="inline-flex flex-1 items-center justify-center gap-2 rounded-lg bg-cyan-700 px-3 py-2.5 text-xs font-bold text-white"><Play size={14} />Start scenario</button> : <button data-testid="button-advance-demo" onClick={advance} className="inline-flex flex-1 items-center justify-center gap-2 rounded-lg bg-[#172634] px-3 py-2.5 text-xs font-bold text-white">{step === steps.length - 1 ? <Check size={14} /> : <ChevronRight size={14} />}{step === steps.length - 1 ? 'Complete drill' : 'Advance checkpoint'}</button>}<button data-testid="button-pause-demo" onClick={() => { setRunning(!running); pushToast(running ? 'Scenario paused' : 'Scenario resumed', 'info'); }} className="rounded-lg border border-slate-200 px-3 py-2.5 text-xs font-bold text-slate-600">{running ? <Square size={14} /> : <Play size={14} />}</button></div></section></div></div>;
}

function SettingsPage({ pushToast }: { pushToast: AppProps['pushToast'] }) {
  const [settings, setSettings] = useState({ critical: true, shift: true, sound: false, compact: false, confirm: true });
  const toggle = (key: keyof typeof settings) => setSettings((current) => ({ ...current, [key]: !current[key] }));
  const Toggle = ({ label, detail, setting }: { label: string; detail: string; setting: keyof typeof settings }) => <button data-testid={`button-toggle-setting-${setting}`} onClick={() => toggle(setting)} className="flex w-full items-center justify-between gap-4 py-3 text-left"><span><span className="block text-xs font-bold">{label}</span><span className="mt-1 block text-[11px] leading-4 text-slate-500">{detail}</span></span><span className={cn('relative h-5 w-9 shrink-0 rounded-full transition-colors', settings[setting] ? 'bg-cyan-700' : 'bg-slate-300')}><span className={cn('absolute top-1 h-3 w-3 rounded-full bg-white transition-transform', settings[setting] ? 'translate-x-5' : 'translate-x-1')} /></span></button>;
  return <div className="mx-auto max-w-[1000px] space-y-5"><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Alert routing" title="Notifications & escalation" /><div className="divide-y divide-slate-100"><Toggle label="Critical incident alerts" detail="Keep critical incidents visible at the top of every queue." setting="critical" /><Toggle label="Shift handover reminders" detail="Notify the active operator 15 minutes before handover." setting="shift" /><Toggle label="Audible local cue" detail="Play a subtle sound on this device for new critical updates." setting="sound" /></div></section><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Workspace" title="Display preferences" /><div className="divide-y divide-slate-100"><Toggle label="Compact data tables" detail="Reduce row height when scanning large resource rosters." setting="compact" /><Toggle label="Confirm dispatch actions" detail="Require a second acknowledgement before dispatching a unit." setting="confirm" /></div></section><section className="rounded-xl border border-slate-200 bg-white p-5"><SectionHeading eyebrow="Control center" title="Operating profile" /><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold text-slate-600">Default location<select data-testid="select-default-location" className="mt-2 w-full rounded-lg border border-slate-200 bg-slate-50 px-3 py-2.5 text-xs outline-none"><option>Bengaluru · Central</option><option>Bengaluru · North</option><option>Bengaluru · East</option></select></label><label className="text-xs font-bold text-slate-600">Timezone<select data-testid="select-timezone" className="mt-2 w-full rounded-lg border border-slate-200 bg-slate-50 px-3 py-2.5 text-xs outline-none"><option>Asia/Kolkata · IST (UTC+5:30)</option></select></label></div><div className="mt-5 flex justify-end border-t border-slate-100 pt-4"><button data-testid="button-save-settings" onClick={() => pushToast('Preferences saved to this workspace', 'success')} className="rounded-lg bg-cyan-700 px-4 py-2.5 text-xs font-bold text-white hover:bg-cyan-800">Save preferences</button></div></section></div>;
}

type AppProps = { pushToast: (message: string, tone?: Toast['tone']) => void };

function RoutedApp({ pushToast }: AppProps) {
  return <Switch><Route path="/" component={() => <Redirect to="/overview" />} /><Route path="/overview" component={() => <Overview pushToast={pushToast} />} /><Route path="/incidents" component={() => <IncidentsPage pushToast={pushToast} />} /><Route path="/vehicles" component={() => <ResourceTablePage kind="vehicles" pushToast={pushToast} />} /><Route path="/drivers" component={() => <ResourceTablePage kind="drivers" pushToast={pushToast} />} /><Route path="/emergency-services" component={() => <ServicesPage pushToast={pushToast} />} /><Route path="/response-team" component={() => <TeamsPage pushToast={pushToast} />} /><Route path="/history" component={() => <HistoryPage pushToast={pushToast} />} /><Route path="/analytics" component={AnalyticsPage} /><Route path="/demo" component={() => <DemoPage pushToast={pushToast} />} /><Route path="/settings" component={() => <SettingsPage pushToast={pushToast} />} /><Route><NotFoundPage /></Route></Switch>;
}

function NotFoundPage() {
  const [, setLocation] = useLocation();
  return <div className="flex min-h-[60vh] flex-col items-center justify-center text-center"><div className="flex h-12 w-12 items-center justify-center rounded-xl bg-amber-100 text-amber-700"><Command size={22} /></div><h1 className="mt-4 text-xl font-extrabold">Route not found</h1><p className="mt-2 text-sm text-slate-500">This control center view does not exist.</p><button data-testid="button-return-overview" onClick={() => setLocation('/overview')} className="mt-5 rounded-lg bg-cyan-700 px-4 py-2.5 text-xs font-bold text-white">Return to overview</button></div>;
}

function App() {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const pushToast = (message: string, tone: Toast['tone'] = 'info') => {
    const id = Date.now();
    setToasts((current) => [...current.slice(-2), { id, message, tone }]);
    window.setTimeout(() => setToasts((current) => current.filter((toast) => toast.id !== id)), 3200);
  };
  return <AppShell toasts={toasts} pushToast={pushToast}><RoutedApp pushToast={pushToast} /></AppShell>;
}

export default App;